<?php
require_once __DIR__ . '/config.php';
require_once __DIR__ . '/functions.php';
$admin = require_admin($pdo);
$filter = (string)($_GET['status'] ?? 'pending');
$allowed = ['pending','correction_required','approved','rejected','all'];
if (!in_array($filter, $allowed, true)) $filter = 'pending';
$sql = "SELECT u.*, reviewer.full_name AS reviewer_name FROM users u LEFT JOIN users reviewer ON reviewer.id=u.reviewed_by WHERE u.role='student'";
$params = [];
if ($filter !== 'all') { $sql .= ' AND u.status = ?'; $params[] = $filter; }
$sql .= " ORDER BY CASE u.status WHEN 'pending' THEN 0 WHEN 'correction_required' THEN 1 ELSE 2 END, u.created_at ASC";
$stmt = $pdo->prepare($sql); $stmt->execute($params); $applications = $stmt->fetchAll();
render_header('Student approval', 'applications');
?>
<div class="page-header"><div><div class="eyebrow"><span class="pulse-dot"></span> ACCOUNT ACCESS CONTROL</div><h1>Student approval</h1><p>Review student ID photos, live selfies, and extracted details. Approve only after checking the information against an official school record.</p></div></div>
<div class="toolbar"><div class="filter-pills"><?php foreach (['pending'=>'Pending','correction_required'=>'Needs correction','approved'=>'Approved','rejected'=>'Rejected','all'=>'All applications'] as $value=>$label): ?><a class="filter-pill <?= $filter===$value?'active':'' ?>" href="?status=<?= e($value) ?>"><?= e($label) ?></a><?php endforeach; ?></div><span class="small-muted"><?= count($applications) ?> application(s)</span></div>
<?php if (!$applications): ?><div class="panel"><div class="empty-state"><div class="empty-icon">✓</div><strong>No applications in this view</strong><p>When a student submits a registration, it will appear here for review.</p></div></div><?php else: ?><div class="application-list">
<?php foreach ($applications as $app): ?><article class="panel application-card" id="application-<?= (int)$app['id'] ?>"><div class="application-card-head"><div class="application-person"><span class="avatar avatar-large"><?= e(strtoupper(substr($app['full_name'],0,1))) ?></span><div><h2><?= e($app['full_name']) ?></h2><p><?= e($app['student_id']) ?> · <?= e($app['program']) ?></p><small>Submitted <?= e(date('M j, Y · g:i A', strtotime($app['created_at']))) ?></small></div></div><span class="status-badge status-<?= e(status_class($app['status'])) ?>"><?= e(status_label($app['status'])) ?></span></div>
<div class="photo-review-grid"><div class="photo-review-box"><strong>School ID photo</strong><?php if ($app['id_photo_path']): ?><img loading="lazy" src="<?= e(private_image_url('id', (int)$app['id'])) ?>" alt="School ID submitted for <?= e($app['full_name']) ?>"><?php else: ?><div class="photo-missing">No ID photo saved</div><?php endif; ?></div><div class="photo-review-box"><strong>Live selfie</strong><?php if ($app['selfie_photo_path']): ?><img class="admin-selfie-image" loading="lazy" src="<?= e(private_image_url('selfie', (int)$app['id'])) ?>" alt="Selfie submitted by <?= e($app['full_name']) ?>"><?php else: ?><div class="photo-missing">No selfie saved</div><?php endif; ?></div></div>
<div class="application-details"><div><small>Student ID Number</small><strong><?= e($app['student_id']) ?></strong></div><div><small>Full name</small><strong><?= e($app['full_name']) ?></strong></div><div><small>Program / Course</small><strong><?= e($app['program']) ?></strong></div><div><small>Privacy notice acknowledged</small><strong><?= $app['consent_privacy'] ? 'Yes' : 'No' ?></strong></div></div>
<?php if ($app['review_note']): ?><div class="review-note"><strong>Previous review note:</strong> <?= e($app['review_note']) ?></div><?php endif; ?>
<?php if (in_array($app['status'], ['pending','correction_required'], true)): ?><form method="post" action="application_action.php" class="application-action-form"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$app['id'] ?>"><label class="field-label" for="note-<?= (int)$app['id'] ?>">Review note (required for rejection or correction)</label><textarea class="textarea-note" id="note-<?= (int)$app['id'] ?>" name="review_note" placeholder="Example: Please retake the ID photo so the student number is readable."></textarea><div class="action-row"><button class="btn btn-success" name="decision" value="approve" type="submit">✓ Approve account</button><button class="btn btn-outline" name="decision" value="correction_required" type="submit">↻ Request correction</button><button class="btn btn-danger" name="decision" value="reject" type="submit">× Reject application</button></div></form><?php else: ?><div class="review-note">Reviewed by <?= e($app['reviewer_name'] ?: 'School Admin') ?><?= $app['reviewed_at'] ? ' on ' . e(date('M j, Y', strtotime($app['reviewed_at']))) : '' ?>.</div><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?>
<?php render_footer(); ?>
